/**
 * Persona API Types
 * Type definitions for persona-related endpoints
 */

import { ApiResponse, PaginationInfo } from "../shared/types";

/**
 * Persona Rating
 */
export type PersonaRating = "SFW" | "NSFW";

/**
 * Persona Visibility
 */
export type PersonaVisibility = "public" | "private";

/**
 * Persona Image
 */
export interface PersonaImage {
  url: string;
  width?: number;
  height?: number;
}

/**
 * Persona
 */
export interface Persona {
  id: string;
  userId: string;
  name: string;
  slug: string;
  description?: string | null;
  visibility: PersonaVisibility;
  rating: PersonaRating;
  isFavourite: boolean;
  isSaved: boolean;
  avatar?: PersonaImage | null;
  backgroundImg?: PersonaImage | null;
  tags: string[];
  lorebookId?: string | null;
  createdAt: string;
  updatedAt: string;
  characters?: Array<{ id: string; name: string }>;
  lorebook?: { id: string; name: string } | null;
}

/**
 * Create Persona Request
 * Supports both File objects (for multipart/form-data) and strings (for JSON)
 */
export interface CreatePersonaRequest {
  name: string;
  description?: string;
  rating: PersonaRating;
  visibility: PersonaVisibility;
  tags?: string[];
  favourite?: boolean;
  avatar?: File | string;
  backgroundImg?: File | string;
  lorebookId?: string;
}

/**
 * Update Persona Request
 * Supports both File objects (for multipart/form-data) and strings (for JSON)
 * All fields are optional for updates
 */
export interface UpdatePersonaRequest {
  name?: string;
  description?: string;
  rating?: PersonaRating;
  visibility?: PersonaVisibility;
  tags?: string[];
  favourite?: boolean;
  avatar?: File | string;
  backgroundImg?: File | string;
  lorebookId?: string | null;
}

/**
 * Persona List Filters
 */
export interface PersonaListFilters {
  page?: number;
  limit?: number;
  search?: string;
  rating?: PersonaRating;
  visibility?: PersonaVisibility;
  tags?: string[];
  excludeTags?: string[];
  isFavourite?: boolean;
  isSaved?: boolean;
  sortBy?: "createdAt" | "updatedAt" | "name";
  sortOrder?: "asc" | "desc";
}

/**
 * Pagination Info
 */


/**
 * Create Persona Response
 */
export interface CreatePersonaResponse {
  persona: Persona;
}

/**
 * Update Persona Response
 */
export interface UpdatePersonaResponse {
  persona: Persona;
}

/**
 * Get Persona Response
 */
export interface GetPersonaResponse {
  persona: Persona;
}

/**
 * List Personas Response
 */
export interface ListPersonasResponse {
  personas: Persona[];
  pagination: PaginationInfo;
}

/**
 * Batch Delete Personas Response
 */
export interface BatchDeletePersonasResponse {
  deleted: number;
  failed: number;
  message: string;
}

/**
 * Import Persona Response
 */
export interface ImportPersonaResponse {
  persona: Persona;
}

/**
 * Bulk Import Personas Response
 */
export interface BulkImportPersonasResponse {
  success: number;
  failed: number;
  personas: Persona[];
  errors: Array<{ name: string; error: string }>;
}

/**
 * Duplicate Persona Response
 */
export interface DuplicatePersonaResponse {
  persona: Persona;
}

/**
 * Batch Duplicate Personas Response
 */
export interface BatchDuplicatePersonasResponse {
  success: number;
  failed: number;
  personas: Persona[];
  message: string;
}

/**
 * API Response Types
 */
export type CreatePersonaApiResponse = ApiResponse<CreatePersonaResponse>;
export type UpdatePersonaApiResponse = ApiResponse<UpdatePersonaResponse>;
export type GetPersonaApiResponse = ApiResponse<GetPersonaResponse>;
export type ListPersonasApiResponse = ApiResponse<ListPersonasResponse>;
export type BatchDeletePersonasApiResponse = ApiResponse<BatchDeletePersonasResponse>;
export type ImportPersonaApiResponse = ApiResponse<ImportPersonaResponse>;
export type BulkImportPersonasApiResponse = ApiResponse<BulkImportPersonasResponse>;
export type DuplicatePersonaApiResponse = ApiResponse<DuplicatePersonaResponse>;
export type BatchDuplicatePersonasApiResponse = ApiResponse<BatchDuplicatePersonasResponse>;

